&lt;td style=&quot;width: 16.4513%; height: 86.7812px;&quot;&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Month 0–1&lt;/span&gt;&lt;/p&gt;
&lt;/td&gt;
&lt;td style=&quot;width: 16.2664%; height: 86.7812px;&quot;&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Learn our current process&lt;/span&gt;&lt;/p&gt;
&lt;/td&gt;
&lt;td style=&quot;width: 67.4686%; height: 86.7812px;&quot;&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Learn our CM plan, PLM structure, change workflow and document system. Join every change board and list the gaps against EIA-649C&lt;/span&gt;&lt;/p&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;tr style=&quot;height: 86.7812px;&quot;&gt;
